import{_ as e,o as t,c as a,a5 as n}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"基于 Lerna 管理 packages 的 Monorepo 项目最佳实践","description":"原创 孔垂亮 vivo互联网技术;) 2019 07 31 对于维护过多个package的同学来说，都会遇到一个选择题，这些package是放在一个仓库里维护还是放在多个仓库里单独维护，本文通过一个示例讲述了如何基于Lerna管理多个package，并和其它工具整合，打造高效、完。","frontmatter":{"title":"基于 Lerna 管理 packages 的 Monorepo 项目最佳实践","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"原创 孔垂亮 vivo互联网技术;) 2019 07 31 对于维护过多个package的同学来说，都会遇到一个选择题，这些package是放在一个仓库里维护还是放在多个仓库里单独维护，本文通过一个示例讲述了如何基于Lerna管理多个package，并和其它工具整合，打造高效、完。","sidebarWeight":61,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vue3/与vue2的比较/基于 Lerna 管理 packages 的 Monorepo 项目最佳实践.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/与vue2的比较/基于 Lerna 管理 packages 的 Monorepo 项目最佳实践.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/与vue2的比较/基于 Lerna 管理 packages 的 Monorepo 项目最佳实践.md"}'),p={name:"posts/Vue系统教程/03-响应式与组合式 API/与vue2的比较/基于 Lerna 管理 packages 的 Monorepo 项目最佳实践.md"};function i(r,o,u,s,l,c){return t(),a("div",null,[...o[0]||(o[0]=[n('<div><h1 id="基于-lerna-管理-packages-的-monorepo-项目最佳实践" tabindex="-1">基于 Lerna 管理 packages 的 Monorepo 项目最佳实践 <a class="header-anchor" href="#基于-lerna-管理-packages-的-monorepo-项目最佳实践" aria-label="Permalink to &quot;基于 Lerna 管理 packages 的 Monorepo 项目最佳实践&quot;">​</a></h1><blockquote><p>本节目标：理解“基于 Lerna 管理 packages 的 Monorepo 项目最佳实践”的核心思路，并能把它用于实际开发或面试表达。 原创 孔垂亮 vivo互联网技术;) <em>2019-07-31</em> 对于维护过多个package的同学来说，都会遇到一个选择题，这些package是放在一个仓库里维护还是放在多个仓库里单独维护，本文通过一个示例讲述了如何基于Lerna管理多个package，并和其它工具整合，打造高效、完美的工作流，最终形成一个最佳实践</p></blockquote><p>背景</p><p>最近在工作中接触到一个项目，这个项目是维护一套 CLI，发到 npm 上供开发者使用。先看一张图： 项目仓库中的根目录上就三个子模块的文件夹，分别对应三个 package，在熟悉了构建和发布流程后，有点傻了。工作流程如图中所示：</p><ol><li>使用webpack、babel和uglifyjs把 pkg-a 的 src 编译到 dist</li><li>使用webpack、babel和uglifyjs把 pkg-b 的 src 编译到 dist</li><li>使用webpack、babel和uglifyjs把 pkg-main 的 src 编译到 dist</li><li>最后使用拷贝文件的方式，把pkg-main、pkg-a、pkg-b中编译后的文件组装到 pkg-npm 中，最终用于发布到 npm 上去。</li></ol><p><strong>痛点</strong></p><ol><li>**不好调试。**因为最终的包是通过文件拷贝的方式组装到一起的，并且都是压缩过的，无法组建一个自上到下的调试流程（实际工作中只能加log，然后重新把包编译组装一遍看效果）</li><li>**包的依赖关系不清晰。**pkg-a、pkg-b索性没有版本管理，更像是源码级别的，但逻辑又比较独立。pkg-main中的package.json最终会拷贝到 pkg-npm 中，但又依赖pkg-a、pkg-b中的某些包，所以要把pkg-a、pkg-b中的依赖合并到pkg-main中。pkg-main和pkg-npm的package.json耦合在一起，导致一些本来是工程的开发依赖也会发布到 npm 上去，变成pkg-npm 的依赖包。</li><li>**依赖的包冗余。**可以看到，pkg-a、pkg-b、pkg-main要分别编译，都依赖了babel、webpack等，要分别 cd 到各个目录安装依赖。</li><li><strong>发布需要手动修改版本号。</strong> 因为最终只发布了一个包，但实际逻辑要求这个包即要全局安装又要本地安装，业务没有拆开，导致要安装两遍。耦合一起，即便使用 npm link 也会导致调试困难，</li><li><strong>发版没有 CHANGELOG.md。</strong> 因为pkg-a、pkg-b都没有真正管理版本，所以也没有完善的CHANGELOG来记录自上个版本发布已来的变动。</li></ol><p>整个项目像是一个没有被管理起来的 Monorepo。那什么又是 Monorepo 呢？</p><p>Monorepo vs Multirepo</p><p>Monorepo 的全称是 monolithic repository，即单体式仓库，与之对应的是 Multirepo(multiple repository)，这里的“单”和“多”是指每个仓库中所管理的模块数量。</p><p>Multirepo 是比较传统的做法，即每一个 package 都单独用一个仓库来进行管理。例如：Rollup, ...</p><p>Monorep 是把所有相关的 package 都放在一个仓库里进行管理，<strong>每个 package 独立发布</strong>。例如：React, Angular, Babel, Jest, Umijs, Vue ...</p><p>一图胜千言： 当然到底哪一种管理方式更好，仁者见仁，智者见智。前者允许多元化发展（各项目可以有自己的构建工具、依赖管理策略、单元测试方法），后者希望集中管理，减少项目间的差异带来的沟通成本。</p><p>虽然拆分子仓库、拆分子 npm 包是进行项目隔离的天然方案，但当仓库内容出现关联时，没有任何一种调试方式比源码放在一起更高效。</p><p>结合我们项目的实际场景和业务需要，天然的 MonoRepo ! 因为工程化的最终目的是让业务开发可以 100% 聚焦在业务逻辑上，那么这不仅仅是脚手架、框架需要从自动化、设计上解决的问题，这涉及到仓库管理的设计。</p><p>一个理想的开发环境可以抽象成这样： <strong>“只关心业务代码，可以直接跨业务复用而不关心复用方式，调试时所有代码都在源码中。”</strong></p><p>在前端开发环境中，多 Git Repo，多 npm 则是这个理想的阻力，它们导致复用要关心版本号，调试需要 npm link。而这些是 MonoRepo 最大的优势。</p><p>上图中提到的利用相关工具就是今天的主角 Lerna ! Lerna是业界知名度最高的 Monorepo 管理工具，功能完整。</p><p>Lerna</p><p>一、Lerna 是什么 A tool for managing JavaScript projects with multiple packages. Lerna is a tool that optimizes the workflow around managing multi-package repositories with git and npm.</p><p>Lerna 是一个管理多个 npm 模块的工具，是 Babel 自己用来维护自己的 Monorepo 并开源出的一个项目。优化维护多包的工作流，解决多个包互相依赖，且发布需要手动维护多个包的问题。</p><p>Lerna 现在已经被很多著名的项目组织使用，如：Babel, React, Vue, Angular, Ember, Meteor, Jest 。</p><p>一个基本的 Lerna 管理的仓库结构如下：</p><p><strong>安装</strong> 推荐全局安装，因为会经常用到 lerna 命令 npm i -g lerna</p><p><strong>项目构建</strong></p><p>1.初始化 lerna init init 命令详情 请参考 lerna init 其中 package.json &amp; lerna.json 如下: // package.json{ &quot;name&quot;: &quot;root&quot;, &quot;private&quot;: true, // 私有的，不会被发布，是管理整个项目，与要发布到npm的解耦 &quot;devDependencies&quot;: { &quot;lerna&quot;: &quot;^3.15.0&quot; }} // lerna.json{ &quot;packages&quot;: [ &quot;packages/*&quot; ], &quot;version&quot;: &quot;0.0.0&quot;} (滑动查看）</p><p>2.增加两个 packages lerna create @mo-demo/clilerna create @mo-demo/cli-shared-utils (滑动查看） create 命令详情 请参考 lerna create 3.分别给相应的 package 增加依赖模块</p><p>lerna add chalk // 为所有 package 增加 chalk 模块lerna add semver --scope @mo-demo/cli-shared-utils // 为 @mo-demo/cli-shared-utils 增加 semver 模块lerna add @mo-demo/cli-shared-utils --scope @mo-demo/cli // 增加内部模块之间的依赖 (滑动查看） add 命令详情 请参考 lerna add 4.发布 lerna publish publish 命令详情 请参考 lerna publish 如下是发布的情况，lerna会让你选择要发布的版本号，我发了@0.0.1-alpha.0 的版本。</p><p><strong>发布 npm 包需要登陆 npm 账号</strong></p><p>5.安装依赖包 &amp; 清理依赖包</p><p>上述1-4步已经包含了 Lerna 整个生命周期的过程了，但当我们维护这个项目时，新拉下来仓库的代码后，需要为各个 package 安装依赖包。</p><p>我们在第4步 lerna add 时也发现了，为某个 package 安装的包被放到了这个 package 目录下的 node_modules 目录下。这样对于多个 package 都依赖的包，会被多个 package 安装多次，并且每个 package 下都维护 node_modules ，也不清爽。于是我们使用 --hoist 来把每个 package 下的依赖包都提升到工程根目录，来降低安装以及管理的成本。 lerna bootstrap --hoist bootstrap 命令详情 请参考 lerna bootstrap</p><p><strong>为了省去每次都输入 --hoist 参数的麻烦，可以在 lerna.json 配置：</strong> { &quot;packages&quot;: [ &quot;packages/*&quot; ], &quot;command&quot;: { &quot;bootstrap&quot;: { &quot;hoist&quot;: true } }, &quot;version&quot;: &quot;0.0.1-alpha.0&quot;}</p><p>配置好后，对于之前依赖包已经被安装到各个 package 下的情况，我们只需要清理一下安装的依赖即可： lerna clean</p><p>然后执行 lerna bootstrap 即可看到 package 的依赖都被安装到根目录下的 node_modules 中了。</p><p>Lerna的最佳实践</p><p>lerna不负责构建，测试等任务，它提出了一种集中管理package的目录模式，提供了一套自动化管理程序，让开发者不必再深耕到具体的组件里维护内容，在项目根目录就可以全局掌控，基于 npm scripts，使用者可以很好地完成组件构建，代码格式化等操作。接下来我们就来看看，如果基于 Lerna，并结合其它工具来搭建 Monorepo 项目的最佳实践。</p><p>一、优雅的提交</p><p>1.commitizen &amp;&amp; cz-lerna-changelog</p><p>commitizen 是用来格式化 git commit message 的工具，它提供了一种问询式的方式去获取所需的提交信息。</p><p>cz-lerna-changelog 是专门为 Lerna 项目量身定制的提交规范，在问询的过程，会有类似影响哪些 package 的选择。如下：</p><p>我们使用 commitizen 和 cz-lerna-changelog 来规范提交，为后面自动生成日志作好准备。</p><p>因为这是整个工程的开发依赖，所以在根目录安装： npm i -D commitizennpm i -D cz-lerna-changelog</p><p>安装完成后，在 package.json 中增加 config 字段，把 cz-lerna-changelog 配置给 commitizen。同时因为commitizen不是全局安全的，所以需要添加 scripts 脚本来执行 git-cz { &quot;name&quot;: &quot;root&quot;, &quot;private&quot;: true, &quot;scripts&quot;: { &quot;c&quot;: &quot;git-cz&quot; }, &quot;config&quot;: { &quot;commitizen&quot;: { &quot;path&quot;: &quot;./node_modules/cz-lerna-changelog&quot; } }, &quot;devDependencies&quot;: { &quot;commitizen&quot;: &quot;^3.1.1&quot;, &quot;cz-lerna-changelog&quot;: &quot;^2.0.2&quot;, &quot;lerna&quot;: &quot;^3.15.0&quot; }} (滑动查看）</p><p>之后在常规的开发中就可以使用 npm run c 来根据提示一步一步输入，来完成代码的提交。</p><p>2.commitlint &amp;&amp; husky</p><p>上面我们使用了 commitizen 来规范提交，但这个要靠开发自觉使用 npm run c 。万一忘记了，或者直接使用 git commit 提交怎么办？答案就是在提交时对提交信息进行校验，如果不符合要求就不让提交，并提示。校验的工作由 commitlint 来完成，校验的时机则由 husky 来指定。husky 继承了 Git 下所有的钩子，在触发钩子的时候，husky 可以阻止不合法的 commit,push 等等。 // 安装 commitlint 以及要遵守的规范npm i -D @commitlint/cli @commitlint/config-conventional (滑动查看） // 在工程根目录为 commitlint 增加配置文件 commitlint.config.js 为commitlint 指定相应的规范module.exports = { extends: [&#39;@commitlint/config-conventional&#39;] } (滑动查看） // 安装 huskynpm i -D husky // 在 package.json 中增加如下配置&quot;husky&quot;: { &quot;hooks&quot;: { &quot;commit-msg&quot;: &quot;commitlint -E HUSKY_GIT_PARAMS&quot; }} (滑动查看）</p><p>&quot;commit-msg&quot;是git提交时校验提交信息的钩子，当触发时便会使用 commitlit 来校验。安装配置完成后，想通过 git commit 或者其它第三方工具提交时，只要提交信息不符合规范就无法提交。从而约束开发者使用 npm run c 来提交。</p><p>3.standardjs &amp;&amp; lint-staged</p><p>除了规范提交信息，代码本身肯定也少了靠规范来统一风格。</p><p>standardjs就是完整的一套 JavaScript 代码规范，自带 linter &amp; 代码自动修正。它无需配置，自动格式化代码并修正，提前发现风格以及程序问题。</p><p>lint-staged staged 是 Git 里的概念，表示暂存区，lint-staged 表示只检查并矫正暂存区中的文件。一来提高校验效率，二来可以为老的项目带去巨大的方便。 // 安装npm i -D standard lint-staged // package.json{ &quot;name&quot;: &quot;root&quot;, &quot;private&quot;: true, &quot;scripts&quot;: { &quot;c&quot;: &quot;git-cz&quot; }, &quot;config&quot;: { &quot;commitizen&quot;: { &quot;path&quot;: &quot;./node_modules/cz-lerna-changelog&quot; } }, &quot;husky&quot;: { &quot;hooks&quot;: { &quot;pre-commit&quot;: &quot;lint-staged&quot;, &quot;commit-msg&quot;: &quot;commitlint -E HUSKY_GIT_PARAMS&quot; } }, &quot;lint-staged&quot;: { &quot;*.js&quot;: [ &quot;standard --fix&quot;, &quot;git add&quot; ] }, &quot;devDependencies&quot;: { &quot;@commitlint/cli&quot;: &quot;^8.1.0&quot;, &quot;@commitlint/config-conventional&quot;: &quot;^8.1.0&quot;, &quot;commitizen&quot;: &quot;^3.1.1&quot;, &quot;cz-lerna-changelog&quot;: &quot;^2.0.2&quot;, &quot;husky&quot;: &quot;^3.0.0&quot;, &quot;lerna&quot;: &quot;^3.15.0&quot;, &quot;lint-staged&quot;: &quot;^9.2.0&quot;, &quot;standard&quot;: &quot;^13.0.2&quot; }} (滑动查看）</p><p>安装完成后，在 package.json 增加 lint-staged 配置，如上所示表示对暂存区中的 js 文件执行 standard --fix 校验并自动修复。那什么时候去校验呢，就又用到了上面安装的 husky ，husky的配置中增加&#39;pre-commit&#39;的钩子用来执行 lint-staged 的校验操作，如上所示。</p><p>此时提交 js 文件时，便会自动修正并校验错误。即保证了代码风格统一，又能提高代码质量。</p><p>二、自动生成日志</p><p>有了之前的规范提交，自动生成日志便水到渠成了。再详细看下 lerna publish 时做了哪些事情：</p><p>1.调用 lerna version</p><ul><li>找出从上一个版本发布以来有过变更的 package</li><li>提示开发者确定要发布的版本号</li><li>将所有更新过的的 package 中的package.json的version字段更新</li><li>将依赖更新过的 package 的 包中的依赖版本号更新</li><li>更新 lerna.json 中的 version 字段</li><li>提交上述修改，并打一个 tag</li><li>推送到 git 仓库</li></ul><p>2.使用 npm publish 将新版本推送到 npm</p><p>CHANGELOG 很明显是和 version 一一对应的，所以需要在 lerna version 中想办法，查看 lerna version 命令的详细说明后，会看到一个配置参数 --conventional-commits。没错，只要我们按规范提交后，在 lerna version 的过程中会便会自动生成当前这个版本的 CHANGELOG。为了方便，不用每次输入参数，可以配置在 lerna.json中，如下： { &quot;packages&quot;: [ &quot;packages/<em>&quot; ], &quot;command&quot;: { &quot;bootstrap&quot;: { &quot;hoist&quot;: true }, &quot;version&quot;: { &quot;conventionalCommits&quot;: true } }, &quot;ignoreChanges&quot;: [ &quot;**/</em>.md&quot; ], &quot;version&quot;: &quot;0.0.1-alpha.1&quot;}</p><p>lerna version 会检测从上一个版本发布以来的变动，但有一些文件的提交，我们不希望触发版本的变动，譬如 .md 文件的修改，并没有实际引起 package 逻辑的变化，不应该触发版本的变更。可以通过 ignoreChanges 配置排除。如上。 实际 lerna version 很少直接使用，因为它包含在 lerna publish 中了，直接使用 lerna publish就好了。</p><p>Lerna 在管理 package 的版本号上，提供了两种模式供选择 Fixed or Independent。默认是 Fixed，更多细节，以及 Lerna 的更多玩法，请参考官网文档： _<a href="https://github.com/lerna/lerna/blob/master/README.md_" target="_blank" rel="noreferrer">https://github.com/lerna/lerna/blob/master/README.md_</a></p><p>三、编译、压缩、调试</p><p><strong>采用 Monorepo 结构的项目，各个 package 的结构最好保持统一。</strong></p><p>根据目前的项目状况，设计如下：</p><ol><li>各 package 入口统一为 index.js</li><li>各 package 源码入口统一为 src/index.js</li><li>各 package 编译入口统一为 dist/index.js</li><li>各 package 统一使用 ES6 语法、使用 Babel 编译、压缩并输出到 dist</li><li>各 package 发布时只发布 dist 目录，不发布 src 目录</li><li>各 package 注入 LOCAL_DEBUG 环境变量， 在index.js 中区分是调试还是发布环境，调试环境 ruquire(./src/index.js) 保证所有源码可调试。发布环境 ruquire(./dist/index.js) 保证所有源码不被发布。</li></ol><p>因为 dist 是 Babel 编译后的目录，我们在搜索时不希望搜索它的内容，所以在工程的设置中把 dist 目录排除在搜索的范围之外。</p><p>接下来，我们按上面的规范，搭建 package 的结构。</p><p><strong>首先安装依赖</strong> npm i -D @babel/cli @babel/core @babel/preset-env // 使用 Babel 必备 详见官网用法npm i -D @babel/node // 用于调试 因为用了 import&amp;export 等 ES6 的语法npm i -D babel-preset-minify // 用于压缩代码 (滑动查看）</p><p>由于各 package 的结构统一，所以类似 Babel 这样的工具，只在根目录安装就好了，不需要在各 package 中安装，简直是清爽的要死了。</p><p><strong>增加 Babel 配置</strong> // 根目录新建 babel.config.jsmodule.exports = function (api) { api.cache(true) const presets = [ [ &#39;@babel/env&#39;, { targets: { node: &#39;8.9&#39; } } ] ] // 非本地调试模式才压缩代码，不然调试看不到实际变量名 if (!process.env[&#39;LOCAL_DEBUG&#39;]) { presets.push([ &#39;minify&#39; ]) } const plugins = [] return { presets, plugins, ignore: [&#39;node_modules&#39;] }} (滑动查看）</p><p><strong>修改各 package 的代码</strong> // @mo-demo/cli/index.jsif (process.env.LOCAL_DEBUG) { require(&#39;./src/index&#39;) // 如果是调试模式，加载src中的源码} else { require(&#39;./dist/index&#39;) // dist会发到npm} // @mo-demo/cli/src/index.jsimport { log } from &#39;@mo-demo/cli-shared-utils&#39; // 从 utils 模块引入依赖并使用 log 函数log(&#39;cli/index.js as cli entry exec!&#39;) // @mo-demo/cli/package.json{ &quot;main&quot;: &quot;index.js&quot;, &quot;files&quot;: [ &quot;dist&quot; // 发布 dist ]} // @mo-demo/cli-shared-utils/index.jsif (process.env.LOCAL_DEBUG) { module.exports = require(&#39;./src/index&#39;) // 如果是调试模式，加载src中的源码} else { module.exports = require(&#39;./dist/index&#39;) // dist会发到npm} // @mo-demo/cli-shared-utils/src/index.jsconst log = function (str) { console.log(str)}export { //导出 log 接口 log} // @mo-demo/cli-shared-utils/package.json{ &quot;main&quot;: &quot;index.js&quot;, &quot;files&quot;: [ &quot;dist&quot; ]} (滑动查看）</p><p><strong>修改发布的脚本</strong></p><p>npm run b 用来对各 pacakge 执行 babel 的编译，从 src 目录输出出 dist 目录，使用根目录的配置文件 babel.config.js。</p><p>npm run p 用来取代 lerna publish，在 publish 前先执行 npm run b来编译。</p><p>其它常用的 lerna 命令也添加到 scripts 中来，方便使用。 // 工程根目录 package.json &quot;scripts&quot;: { &quot;c&quot;: &quot;git-cz&quot;, &quot;i&quot;: &quot;lerna bootstrap&quot;, &quot;u&quot;: &quot;lerna clean&quot;, &quot;p&quot;: &quot;npm run b &amp;&amp; lerna publish&quot;, &quot;b&quot;: &quot;lerna exec -- babel src -d dist --config-file ../../babel.config.js&quot; } (滑动查看）</p><p><strong>调试</strong></p><p>我们使用vscode自带的调试功能调试，也可以使用 Node + Chrome 调试，看开发者习惯。</p><p>我们就 vscode 为例，请参考 _<a href="https://code.visualstudio.com/docs/editor/debugging_%E3%80%82" target="_blank" rel="noreferrer">https://code.visualstudio.com/docs/editor/debugging_。</a></p><p>增加如下调试配置文件： // .vscode/launch.json{ // 使用 IntelliSense 了解相关属性。 // 悬停以查看现有属性的描述。 // 欲了解更多信息，请访问: <a href="https://go.microsoft.com/fwlink/?linkid=830387" target="_blank" rel="noreferrer">https://go.microsoft.com/fwlink/?linkid=830387</a> &quot;version&quot;: &quot;0.2.0&quot;, &quot;configurations&quot;: [ { &quot;type&quot;: &quot;node&quot;, &quot;request&quot;: &quot;launch&quot;, &quot;name&quot;: &quot;debug cli&quot;, &quot;runtimeExecutable&quot;: &quot;${workspaceRoot}/node_modules/.bin/babel-node&quot;, &quot;runtimeArgs&quot;: [ &quot;${workspaceRoot}/packages/cli/src/index.js&quot; ], &quot;env&quot;: { &quot;LOCAL_DEBUG&quot;: &quot;true&quot; }, &quot;console&quot;: &quot;integratedTerminal&quot; } ]} (滑动查看）</p><p>因为 src 的代码是 ES6 的，所以要使用 babel-node去跑调试，@babel/node 已经在前面安装过了。</p><p>**最棒的是，可以直接使用单步调试，调到依赖的模块中去，**如上图，我们要执行 @mo-demo/cli-shared-utils 模块中的 log 方法，单步进入，会直接跳到 @mo-demo/cli-shared-utils src 源码中去执行。如下图</p><p>结语</p><p>到这里，基本上已经构建了基于 Lerna 管理 packages 的 Monorepo 项目的最佳实践了，该有的功能都有：</p><ul><li>完善的工作流</li><li>流畅的调试体验</li><li>风格统一的编码</li><li>一键式的发布机制</li><li>完美的更新日志</li><li>……</li></ul><p>当然，Lerna 还有更多的功能等待着你去发掘，还有很多可以结合 Lerna 一起使用的工具。构建一套完善的仓库管理机制，可能它的收益不是一些量化的指标可以衡量出来的，也没有直接的价值输出，但<strong>它能在日常的工作中极大的提高工作效率，解放生产力，节省大量的人力成本。</strong></p><p>参考文献</p><ol><li>手摸手教你玩转 Lerna_<a href="http://www.uedlinker.com/2018/08/17/lerna-trainning/_" target="_blank" rel="noreferrer">http://www.uedlinker.com/2018/08/17/lerna-trainning/_</a></li><li>精读《Monorepo 的优势》_<a href="https://mp.weixin.qq.com/s/f2ehHTNK9rx8jNBUyhSwAA_" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/f2ehHTNK9rx8jNBUyhSwAA_</a></li><li>使用lerna优雅地管理多个package_<a href="https://zhuanlan.zhihu.com/p/35237759_" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/35237759_</a></li><li>用 husky 和 lint-staged 构建超溜的代码检查工作流_<a href="https://segmentfault.com/a/1190000009546913_" target="_blank" rel="noreferrer">https://segmentfault.com/a/1190000009546913_</a> &gt; 来自 &lt;<a href="https://mp.weixin.qq.com/s/NlOn7er0ixY1HO40dq5Gag" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/NlOn7er0ixY1HO40dq5Gag</a>&gt;</li></ol></div>',1)])])}const m=e(p,[["render",i]]);export{g as __pageData,m as default};
